// Story collection UI, canonical character defaults and book text-position controls.
const storyLibrary=document.createElement('section');storyLibrary.id='story-library';storyLibrary.className='wrap section story-library';characterSection.after(storyLibrary);
let storyFilter='all',storySearch='',storyVisible=9,storySearchTimer;
const categoryName=id=>{const c=storyCategories.find(c=>c[0]===id);return c?t(c[1],c[2]):''};
function castName(key,l=lang){return storyCast[key][l==='ar'?'ar':'en']}
function renderStoryLibrary(){const items=storyCatalog.filter(s=>(storyFilter==='all'||s.category===storyFilter)&&(!storySearch||[s.ar,s.en,...s.pages.ar,...s.pages.en].join(' ').toLowerCase().includes(storySearch.toLowerCase())));storyLibrary.innerHTML=`<div class="section-top"><div><span class="overline">${t('عيسى ومدرك وصمود… وحكايات لا تتشابه','ISA, MUDRIK & SOMOUD. ADVENTURES OF THEIR OWN.')}</span><h2>${t('أيّ سرّ سنكتشف اليوم؟','Which secret will we uncover today?')}</h2><p>${t(`${storyCatalog.length} حكاية… اختر حلم اليوم، واترك للمغامرة أن تبدأ.`,`${storyCatalog.length} stories. Pick today’s dream and let the adventure begin.`)}</p></div><label class="story-search">${t('ابحث عن حكاية','Find a story')}<input id="storySearch" type="search" value="${esc(storySearch)}" placeholder="${t('فلج، قمر، فارس…','Falaj, Moon, knight…')}"></label></div><div class="heritage-filters" role="group" aria-label="${t('تصنيف القصص','Story categories')}">${[['all','جميع القصص','All stories'],...storyCategories].map(([id,a,e])=>`<button data-story-filter="${id}" class="${storyFilter===id?'active':''}" aria-pressed="${storyFilter===id}">${t(a,e)} <small>${id==='all'?storyCatalog.length:storyCatalog.filter(s=>s.category===id).length}</small></button>`).join('')}</div><div class="tale-grid">${items.slice(0,storyVisible).map(s=>`<article class="tale-card"><div class="tale-art">${charArt(characterById(s.character))}<span>${esc(categoryName(s.category))}</span></div><div class="tale-copy"><div class="tale-meta"><span>${t('بطولة','Starring')} ${esc(castName(s.lead))}</span><span>${t(s.pages.ar.length+' '+(s.pages.ar.length>10?'صفحة':'صفحات'),s.pages.ar.length+' pages')}</span></div><h3>${esc(charName(s))}</h3><p>${esc(s.pages[lang==='ar'?'ar':'en'][0])}</p><div class="tale-actions"><button class="button" data-read-tale="${s.id}">${t('اقرأ الحكاية','Read story')}</button><button class="button outline" data-create-tale="${s.id}">${t('صمّم الكتاب','Design book')}</button></div></div></article>`).join('')}</div>${items.length?`<div class="story-load-more"><p>${t(`نعرض ${Math.min(storyVisible,items.length)} من ${items.length} حكاية`,`Showing ${Math.min(storyVisible,items.length)} of ${items.length} stories`)}</p>${storyVisible<items.length?`<button class="button outline" id="moreStories">${t('مزيد من الحكايات ↓','More stories ↓')}</button>`:''}</div>`:''}${items.length?'':`<div class="empty">${t('لم نجد حكاية بهذا البحث. جرّب كلمة أخرى.','No stories matched. Try another word.')}</div>`}`;
 storyLibrary.querySelectorAll('[data-story-filter]').forEach(b=>b.onclick=()=>{storyFilter=b.dataset.storyFilter;storyVisible=9;renderStoryLibrary();storyLibrary.querySelector('.heritage-filters .active')?.scrollIntoView({block:'nearest',inline:'nearest'})});if($('#moreStories'))$('#moreStories').onclick=()=>{storyVisible+=9;renderStoryLibrary()};$('#storySearch').oninput=e=>{clearTimeout(storySearchTimer);const value=e.target.value;storySearchTimer=setTimeout(()=>{storySearch=value.trim();storyVisible=9;renderStoryLibrary();$('#storySearch').focus()},250)};$('#storySearch').onkeydown=e=>{if(e.key==='Enter'){clearTimeout(storySearchTimer);storySearch=e.target.value.trim();storyVisible=9;renderStoryLibrary()}};
 storyLibrary.querySelectorAll('[data-read-tale]').forEach(b=>b.onclick=()=>readTale(b.dataset.readTale));storyLibrary.querySelectorAll('[data-create-tale]').forEach(b=>b.onclick=()=>launchTale(b.dataset.createTale));
}
function authoredDraft(s){return{name:castName(s.lead),age:'6',world:s.world,storyLanguage:lang,dedication:'',character:s.character,gender:s.lead==='somoud'?'female':'male',narrative:s.id,landmark:['sea','gulf'].includes(s.category)?'sur':'gardens',tone:'standard',plan:'digital',consent:false,photo:''}}
function readTale(id){const entry=storyCatalog.find(s=>s.id===id);draft=authoredDraft(entry);story=makeSample();page=0;step=2;if(!$('#studio').open)$('#studio').showModal();renderStudio();$('#studio').scrollTop=0;}
function launchTale(id){const entry=storyCatalog.find(s=>s.id===id);draft=authoredDraft(entry);step=0;if(!$('#studio').open)$('#studio').showModal();renderStudio();$('#studio').scrollTop=0;}
const characterDefaultStory={'omani-boy':'falaj-secret','omani-girl':'pomegranate-key',gulf:'pearl-promise',arab:'shadow-library',knight:'banner-valley','knight-girl':'white-horse',sailor:'sail-star',scholar:'paper-bridge',superhero:'lantern-lane',astronaut:'missing-moon',diver:'turtle-track'};
const coreLaunchStory=launchStory;launchStory=function(options={}){const id=characterDefaultStory[options.character];if(id&&(!options.narrative||['original','knight','sailor'].includes(options.narrative))){launchTale(id);draft.character=options.character;renderStudio();return}coreLaunchStory(options);const c=characterById(draft.character),entry=resolveTale(draft);draft.name=castName(entry?.lead||c.givenName||'isa',draft.storyLanguage);if(entry&&!options.character)draft.character=entry.character;renderStudio()};
const originalAuthoredRender=renderStudio;renderStudio=function(){if(step===0&&!draft.name){const entry=resolveTale(draft);draft.name=entry?castName(entry.lead,draft.storyLanguage):castName(characterById(draft.character).givenName||'isa',draft.storyLanguage);if(!draft.character&&entry)draft.character=entry.character;}originalAuthoredRender();if(step===0){const name=$('#heroForm input[name="name"]');name.placeholder=t('عيسى، مدرك، صمود','Isa, Mudrik, Somoud');}if(step===1){const select=$('#narrative');const update=()=>{const entry=resolveTale(draft);if(entry)$('#narrativeSummary').textContent=t(`${entry.pages.ar.length} صفحات · ${entry.ar} · أحداث مترابطة وحوار ومفاجأة وحلّ`,`${entry.pages.en.length} pages · ${entry.en} · A connected plot, dialogue, a surprise and a resolution`)};select.addEventListener('change',()=>{const entry=resolveTale(draft),knownNames=Object.values(storyCast).flatMap(c=>[c.ar,c.en]);if(entry&&knownNames.includes(draft.name)){draft.name=castName(draft.gender==='female'?'somoud':entry.lead==='somoud'?'isa':entry.lead,draft.storyLanguage);draft.character=matchingCharacter(entry.character,heroGender(draft));renderStudio();return}update()});update();}if(step===2&&story?.storyId){$('#modalTitle').textContent=story.title;const badge=$('#studioContent .preview-text .badge');if(badge)badge.textContent=t('قصة أصلية · حبكة متصلة · قابلة للتحرير','Original fiction · A connected plot · Editable');}};
const beforeLibraryLanguage=setLanguage;setLanguage=function(){beforeLibraryLanguage();renderStoryLibrary()};
Object.assign(ar,{exampleTitle:'عيسى وسرّ الفلج الصامت',forestTitle:'عيسى وسرّ الفلج الصامت',forestDesc:'الماء توقّف، والشتلة تنتظر… هل يكفي العثور على أوّل دليل؟',spaceTitle:'صمود والقمر الذي فقد لونه',oceanTitle:'صمود وآثار على الرمل',navExplore:'القصص والشخصيات',feature1:'قصص من ٨–١٢ صفحة وقراءات تاريخية من ٦ صفحات'});
Object.assign(en,{exampleTitle:'Isa and the silent falaj',forestTitle:'Isa and the silent falaj',forestDesc:'The water has stopped. Is finding the first clue enough?',spaceTitle:'Somoud and the Moon’s missing color',oceanTitle:'Somoud and the tracks in the sand',feature1:'8–12-page stories and 6-page historical readings'});
setLanguage();
